                    otherEventWithType: objc2_app_kit::NSEventType::ApplicationDefined,
                    location: objc2_foundation::NSPoint::new(0.0, 0.0),
                    modifierFlags: 0usize,
                    timestamp: 0.0f64,
                    windowNumber: 0isize,
                    context: ptr::null_mut::<AnyObject>(),
                    subtype: 0i16,
                    data1: 0isize,
                    data2: 0isize];
                let _: () = msg_send![app, postEvent: event, atStart: Bool::YES];
            }
        }
    }).detach();
