extern "C-unwind" fn terminate(this: &AnyObject, _: Sel, sender: *mut AnyObject) {
    // A second NSApplication terminate: during its nested termination loop may
    // bypass shouldTerminate entirely. Coalesce at the application entry, too.
    // The ivar is null outside Platform::run; preserve that legacy path.
    unsafe {
        let platform = *mac_platform_ivar(this).load::<*mut c_void>(this);
        if !platform.is_null()
            && (&*(platform as *const MacPlatform)).0.lock().termination_pending.get()
        {
            return;
        }
        let _: () = msg_send![super(this, class!(NSApplication)), terminate: sender];
    }
}

